#include "KS/SRC/ks/igo_widget_shared.h"
#include "NGL/PS2/ngl_ps2_shared.h"

#define NULL 0
#define NEW new
#define FTOI(x) ((int)(x))

class Font
{
public:
	enum HORIZJUST { HORIZJUST_CENTER = 1 };
	enum VERTJUST { VERTJUST_BOTTOM = 2 };
};

class stringx
{
	char *chars;
	void *my_buf;
public:
	stringx(const char *text, int length = -1);
};

class TextString
{
public:
	TextString(Font *, stringx, float, float, int, float,
	           Font::HORIZJUST, Font::VERTJUST, bool, color32);
};

class PhotoWidget : public IGOWidget
{
	PanelQuad *borderPQ;
	int borderCenterX, borderCenterY, borderZ;
	nglTexture *photoTexture;
	nglQuad photoQuad, darkQuad;
	float darkFade;
	float fadeOutAlpha;
	float shownTimer;
	bool timed;
	int photoNum;
	TextString *pointText;
	int score, *scorePtr;
	virtual void SetPointText(void);
public:
	PhotoWidget();
	virtual ~PhotoWidget();
};

__asm__(".equ cons__7stringxPCci, 0x00117C40");
__asm__(".equ cons__10TextStringP4FontG7stringxffifQ24Font9HORIZJUSTQ24Font8VERTJUSTbG7color32, 0x00148150");
__asm__(".equ nglInitQuad__FP7nglQuad, 0x003A67E8");
__asm__(".equ nglSetQuadUV__FP7nglQuadffff, 0x003A6A48");
__asm__(".equ nglSetQuadColor__FP7nglQuadUi, 0x003A6B10");
__asm__(".equ nglSetQuadZ__FP7nglQuadf, 0x003A6A28");
__asm__(".equ nglSetQuadBlend__FP7nglQuadUiT2, 0x003A69D0");

PhotoWidget::PhotoWidget()
{
	borderPQ = NULL;

	photoTexture = NULL;
	shownTimer = 0.0f;
	timed = false;
	fadeOutAlpha = 1.0f;
	photoNum = 0;

	borderCenterX = 437;
	borderCenterY = 265;
	borderZ = 400;

	scorePtr = NULL;
	pointText = NEW TextString(NULL, "", 0, 0, 300, 0.9f, Font::HORIZJUST_CENTER, Font::VERTJUST_BOTTOM, color32(149, 251, 149, 255));

	nglInitQuad(&photoQuad);
	nglSetQuadUV(&photoQuad, 0, 0, 1, 1);
	nglSetQuadColor(&photoQuad, NGL_RGBA32(255, 255, 255, 255));
	nglSetQuadZ(&photoQuad, 300);
	nglSetQuadBlend(&photoQuad, NGLBM_OPAQUE, 0);

	nglInitQuad(&darkQuad);
	nglSetQuadUV(&darkQuad, 0, 0, 1, 1);
	nglSetQuadColor(&darkQuad, NGL_RGBA32(64, 64, 64, FTOI(darkFade*255.0f)));
	nglSetQuadZ(&darkQuad, 250);
	nglSetQuadBlend(&darkQuad, NGLBM_BLEND, 0);
}
